import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"檢舉回報受理項目的詳細說明","description":"","frontmatter":{},"headers":[],"relativePath":"apply/report_detail/index.md","filePath":"apply/report_detail.md"}'),r={name:"apply/report_detail/index.md"};function o(u,l,n,d,h,s){return e(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="檢舉回報受理項目的詳細說明" tabindex="-1">檢舉回報受理項目的詳細說明 <a class="header-anchor" href="#檢舉回報受理項目的詳細說明" aria-label="Permalink to &quot;檢舉回報受理項目的詳細說明&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">注意事項</p><p>受理項目的說明無法涵蓋所有情況，案件是否受理以伺服人員認定之</p></div><h3 id="建築被破壞" tabindex="-1">建築被破壞 <a class="header-anchor" href="#建築被破壞" aria-label="Permalink to &quot;建築被破壞&quot;">​</a></h3><ul><li>不限於形式，房子、農場、設施等都可以</li><li>自然構造如海底神殿、水晶洞等，需經過改造到能明顯看出有玩家佔領才會受理</li></ul><h3 id="物品被偷" tabindex="-1">物品被偷 <a class="header-anchor" href="#物品被偷" aria-label="Permalink to &quot;物品被偷&quot;">​</a></h3><ul><li>放在箱子、桶子、展示框裡等等的物品 <ul><li>可使用<a href="/feature/lock/">告示牌上鎖箱子</a>，以及<a href="/feature/sp_tool/">展示框保護套件</a>來保護你的資產</li></ul></li><li>自行丟出去的物品原則上不受理 <ul><li>如果是傳遞物品給玩家時被攔截可以提出檢舉，並附上文字說明</li></ul></li></ul><h3 id="生物被殺" tabindex="-1">生物被殺 <a class="header-anchor" href="#生物被殺" aria-label="Permalink to &quot;生物被殺&quot;">​</a></h3><ul><li>你<b>圈養</b>起來的生物 <ul><li>要能明確看出來是被人飼養的生物才會受理</li></ul></li><li>你所飼養的寵物 <ul><li>貓、狗、馬等可辨識主人的生物</li><li>例外：跑到公共區域(如商店街、美術館、重生點等)及其周圍時，伺服人員有權直接清除</li></ul></li></ul><h3 id="盜印畫作" tabindex="-1">盜印畫作 <a class="header-anchor" href="#盜印畫作" aria-label="Permalink to &quot;盜印畫作&quot;">​</a></h3><ul><li>玩家的地圖畫沒有同步編號 <ul><li>這很有可能是玩家私下盜印畫作，可提出檢舉由伺服人員協助查證</li></ul></li></ul><h3 id="被其他玩家影響遊玩" tabindex="-1">被其他玩家影響遊玩 <a class="header-anchor" href="#被其他玩家影響遊玩" aria-label="Permalink to &quot;被其他玩家影響遊玩&quot;">​</a></h3><ul><li>PVP關閉時被岩漿、打火石燒；被TNT、終界水晶炸等 <ul><li>PVP開啟時一律不受理</li></ul></li><li>副本服僅受理外掛相關案件，其餘包含搶怪、殺人皆不受理</li><li>其他會影響遊玩的行為</li></ul><h3 id="有玩家做出違反遊玩規範的行為" tabindex="-1">有玩家做出違反<a href="/rule/">遊玩規範</a>的行為 <a class="header-anchor" href="#有玩家做出違反遊玩規範的行為" aria-label="Permalink to &quot;有玩家做出違反[遊玩規範](../rule.md)的行為&quot;">​</a></h3><ul><li>使用外掛/利用遊戲BUG、開分身/使用VPN等</li></ul><p><font size="4"><a href="/apply/report/"><b>點我返回 檢舉回報</b></a></font></p>',15)])])}const _=a(r,[["render",o]]);export{p as __pageData,_ as default};
